ange">&#9823;</i><span><b><?=e((int)($c['supervisor_pending']??0))?> waivers await supervisor review</b><small>Your review is needed</small></span><em>&rsaquo;</em></a><footer><a href="index.php?page=waivers">View all tasks</a></footer></aside></section><section class="card recent-waivers"><header class="recent-header"><h2>Recent waivers</h2><div class="status-tabs" aria-label="Filter waivers by status"><button type="button" class="active" data-quick-status="">All <span><?=e((int)($c['total']??0))?></span></button><button type="button" data-quick-status="DRAFT">Draft <span><?=e((int)($c['drafts']??0))?></span></button><button type="button" data-quick-status="AWAITING EMPLOYEE SIGNATURE">Awaiting employee <span><?=e((int)($c['employee_pending']??0))?></span></button><button type="button" data-quick-status="AWAITING SUPERVISOR">Awaiting supervisor <span><?=e((int)($c['supervisor_pending']??0))?></span></button><button type="button" data-quick-status="COMPLETED">Completed <span><?=e((int)($c['completed']??0))?></span></button></div></header><?=table_html(rows())?></section><?php }
elseif($page==='new-waiver'){require_role(['SYSTEM ADMIN','CLINIC NURSE','HR / CLINIC ADMIN','EMPLOYEE']);$step=max(1,min(6,(int)($_GET['step']??1)));steps6($step);if($step===1){$emps=all("SELECT e.*,d.department_name FROM dbo.acd_mw_employees e LEFT JOIN dbo.acd_mw_departments d ON d.department_id=e.department_id WHERE e.is_active=1 ORDER BY e.full_name");?><section class="card"><h2 class="section-title">Select employee</h2><input id="search" class="search-large" placeholder="Search employee by ID or name"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="start"><div class="employee-results" data-filter><?php foreach($emps as $e):?><label class="employee-choice"><input type="radio" name="employee_id" value="<?=e($e['employee_id'])?>" required><span class="avatar"><?=e(substr($e['full_name'],0,1))?></span><span><b><?=e($e['full_name'])?></b><small><?=e($e['employee_number'].' · '.$e['department_name'].' · '.$e['position'])?></small></span><em>Select</em></label><?php endforeach?></div><button class="btn">Continue →</button></form></section><?php }elseif($step===2){?><section class="card"><h2 class="section-title">Choose waiver type</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="type"><div class="type-grid"><label class="type-card"><input type="radio" name="waiver_type" value="UNFIT_TO_WORK" required><span class="type-icon">↗</span><b>Unfit to work</b><p>Employee continues working despite being advised not to.</p></label><label class="type-card"><input type="radio" name="waiver_type" value="REFUSED_MEDICAL_TREATMENT" required><span class="type-icon">×</span><b>Refused medical treatment</b><p>Employee refuses recommended treatment, evaluation, or transport.</p></label></div><button class="btn">Continue →</button></form></section><?php }elseif($step===3){$d=$_SESSION['waiver_draft']??[];?><section class="card"><div class="document-kicker"><?=e(str_replace('_',' ',$d['type_code']??''))?></div><h2 class="section-title">Waiver details</h2><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="details"><div class="field"><label>Date</label><input disabled value="<?=e(date('F j, Y'))?>"></div><div class="field"><label>Time</label><input disabled value="<?=e(date('g:i A'))?>"></div><div class="field full"><label>Medical / nurse personnel</label><input name="medical_personnel" required></div><div class="field full"><label>Recommendation</label><textarea name="recommendation" required></textarea></div><?php if(($d['type_code']??'')==='REFUSED_MEDICAL_TREATMENT'):?><div class="field"><label>Transportation offered</label><select name="transportation"><?php foreach(TRANSPORTATION_OPTIONS as $x):?><option><?=e($x)?></option><?php endforeach?></select></div><?php endif?><div class="field full"><label>Remarks (optional)</label><textarea name="remarks"></textarea></div><button class="btn">Review waiver →</button></form></section><?php }else{$w=waiver((int)($_GET['id']??0));if(!$w)exit('Waiver not found.');if($step===4){document_html($w,false);?><form method="post" class="document-actions"><?=csrf_field()?><input type="hidden" name="action" value="review"><input type="hidden" name="waiver_id" value="<?=e($w['waiver_id'])?>"><button class="btn">Proceed to sign →</button></form><?php }elseif($step===5){document_html($w,false);?><section class="card sign-panel"><h2>Employee signature</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="employee_sign"><input type="hidden" name="waiver_id" value="<?=e($w['waiver_id'])?>"><div class="checks"><?php foreach(acknowledgments($w['type_code']) as $x):?><label class="check"><input type="checkbox" name="ack[]" value="<?=e($x)?>" required><span><?=e($x)?></span></label><?php endforeach?></div><?=signature_form('employee')?><button class="btn full-btn">Sign waiver →</button></form></section><?php }else{complete_html($w);}}}
elseif($page==='waivers'){?><section class="card"><div class="view-actions"><a class="btn" href="index.php?page=new-waiver&step=1">＋ New waiver</a></div><?=table_html(rows())?></section><?php }
elseif($page==='approvals'){require_role(['SUPERVISOR','SYSTEM ADMIN']);?><section class="card"><?=table_html(rows("WHERE w.status='AWAITING_SUPERVISOR'"),true)?></section><?php }
elseif($page==='approval-sign'){require_role(['SUPERVISOR','SYSTEM ADMIN']);$w=waiver((int)($_GET['id']??0));if(!$w)exit('Not found.');document_html($w,true);?><section class="card sign-panel"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="supervisor_sign"><input type="hidden" name="waiver_id" value="<?=e($w['waiver_id'])?>"><?=signature_form('supervisor')?><button class="btn full-btn">Acknowledge and sign →</button></form></section><?php }
elseif($page==='waiver-view'){$w=waiver((int)($_GET['id']??0));if(!$w)exit('Not found.');if($w['status']==='DRAFT')redirect("index.php?page=new-waiver&step=4&id={$w['waiver_id']}");if($w['status']==='AWAITING_EMPLOYEE_SIGNATURE')redirect("index.php?page=new-waiver&step=5&id={$w['waiver_id']}");if($w['status']==='AWAITING_SUPERVISOR'&&in_array(user()['role_name'],['SUPERVISOR','SYSTEM ADMIN'],true))redirect("index.php?page=approval-sign&id={$w['waiver_id']}");document_html($w,true);?><div class="document-actions"><a class="btn" target="_blank" href="pages/print.php?id=<?=e($w['waiver_id'])?>">Print</a><a class="btn secondary" href="index.php?page=waivers">Back</a></div>
<?php }elseif($page==='audit'){require_role(['SYSTEM ADMIN']);$activityRows=activity_data();$actions=all('SELECT DISTINCT action FROM dbo.acd_mw_activity_logs ORDER BY action');$logUsers=all('SELECT user_id,full_name FROM dbo.acd_mw_users WHERE is_active=1 ORDER BY full_name');$export=$_GET;unset($export['page']);$export['mode']='activity';?><section class="activity-intro compact-intro"><p>Review authentication, waiver lifecycle, printing, and administrative actions.</p><a class="btn secondary" href="export.php?<?=e(http_build_query($export))?>">Export filtered CSV</a></section><section class="card"><form method="get" class="filter-grid"><input type="hidden" name="page" value="audit"><div class="field"><label>Search record</label><input name="q" value="<?=e($_GET['q']??'')?>" placeholder="Description, entity, or ID"></div><div class="field"><label>Action</label><select name="action"><option value="">All actions</option><?php foreach($actions as $a):?><option value="<?=e($a['action'])?>" <?=($_GET['action']??'')===$a['action']?'selected':''?>><?=e(str_replace('_',' ',$a['action']))?></option><?php endforeach?></select></div><div class="field"><label>User</label><select name="user_id"><option value="">All users</option><?php foreach($logUsers as $u):?><option value="<?=e($u['user_id'])?>" <?=((int)($_GET['user_id']??0)===(int)$u['user_id'])?'selected':''?>><?=e($u['full_name'])?></option><?php endforeach?></select></div><div class="field"><label>Date from</label><input type="date" name="from" value="<?=e($_GET['from']??'')?>"></div><div class="field"><label>Date to</label><input type="date" name="to" value="<?=e($_GET['to']??'')?>"></div><div class="filter-actions"><button class="btn">Apply filters</button><a class="btn secondary" href="index.php?page=audit">Clear</a></div></form></section><section class="card section-gap"><div class="view-actions"><span class="muted"><?=e(count($activityRows))?> shown · latest first</span></div><?php if(!$activityRows):?><div class="empty">No activity matches these filters.</div><?php else:?><table><thead><tr><th>Date / time</th><th>User</th><th>Action</th><th>Record</th><th>Description</th></tr></thead><tbody><?php foreach($activityRows as $log):?><tr><td class="nowrap"><?=e(display_datetime($log['created_at']))?></td><td><b><?=e($log['full_name']??'System')?></b><small class="cell-sub"><?=e($log['username']??'Automated event')?></small></td><td><?=badge($log['action'])?></td><td><?=e($log['entity_type'].($log['entity_id']!==null?' #'.$log['entity_id']:''))?></td><td><?=e($log['description'])?></td></tr><?php endforeach?></tbody></table><?php endif?></section>
<?php }else{?><section class="card empty"><p>This waiver administration area is ready for configuration.</p></section><?php }page_end();
function steps6(int $current):void{$l=['Employee','Waiver type','Details','Review','Sign','Complete'];if($current>=2&&$current<6)echo '<div data-waiver-session data-waiver-step="'.$current.'"></div>';?><div class="steps"><?php foreach($l as $i=>$x):$n=$i+1;?><div class="step <?=$n<$current?'done':($n===$current?'current':'')?>"><span><?=$n<$current?'✓':$n?></span><small><?=e($x)?></small></div><?php endforeach?></div><?php }
/**
 * Inline workflow icon family. Every option uses the same rounded 2px stroke
 * and viewBox so the cards feel like one intentional icon set.
 */
function wizard_option_icon(string $name):string
{
 $icons=[
  'employee'=>'<svg class="workflow-option-svg" viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><circle cx="28" cy="18" r="8"/><path d="M12 48v-5.5C12 36.7 17.4 32 24 32h8c6.6 0 12 4.7 12 10.5V48"/><rect x="37" y="34" width="18" height="18" rx="3"/><path d="m42 43 3.2 3.2L51 40.5"/></svg>',
  'unfit'=>'<svg class="workflow-option-svg" viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><circle cx="31" cy="14" r="8"/><path d="M16 52v-7c0-6.6 5.4-12 12-12h6c6.6 0 12 5.4 12 12v7"/><path d="M18 36.5 11 39v13M39 35l11 17M23 33v19M15 23l33 29"/></svg>',
  'medical'=>'<svg class="workflow-option-svg" viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><rect x="13" y="19" width="38" height="35" rx="5"/><path d="M24 19v-4a4 4 0 0 1 4-4h8a4 4 0 0 1 4 4v4M32 29v15M24.5 36.5h15"/><circle cx="32" cy="36.5" r="11"/></svg>'
 ];
 return $icons[$name]??$icons['employee'];
}
function render_new_waiver_design(int $step):void{
 ob_start();
 $employeeIcon=wizard_option_icon('employee');
 $unfitIcon=wizard_option_icon('unfit');
 $medicalIcon=wizard_option_icon('medical');
 $draft=$_SESSION['waiver_draft']??[];
 $editing=null;
 if($step===3 && !empty($_GET['id'])){$editing=one("SELECT TOP 1 w.*,t.type_code FROM dbo.acd_mw_waivers w JOIN dbo.acd_mw_waiver_types t ON t.waiver_type_id=w.waiver_type_id WHERE w.waiver_id=? AND w.status='DRAFT' AND w.created_by=?",[(int)$_GET['id'],(int)user()['user_id']]);if($editing){$draft=['employee_id'=>(int)$editing['employee_id'],'type_code'=>(string)$editing['type_code']];$_SESSION['waiver_draft']=$draft;$_SESSION['editing_waiver_id']=(int)$_GET['id'];}}
 if($step!==3)unset($_SESSION['editing_waiver_id']);
 $employee=null;
 if(!empty($draft['employee_id']))$employee=one("SELECT e.*,d.department_name FROM dbo.acd_mw_employees e LEFT JOIN dbo.acd_mw_departments d ON d.department_id=e.department_id WHERE e.employee_id=?",[(int)$draft['employee_id']]);
 if($step>=4)$employee=$employee?:one("SELECT e.*,d.department_name FROM dbo.acd_mw_employees e LEFT JOIN dbo.acd_mw_departments d ON d.department_id=e.department_id JOIN dbo.acd_mw_waivers w ON w.employee_id=e.employee_id WHERE w.waiver_id=?",[(int)($_GET['id']??0)]);
 steps6($step);
 echo '<div class="new-waiver-page" data-new-waiver-step="'.e($step).'">';
 if($step===1){
  $emps=all("SELECT e.*,d.department_name FROM dbo.acd_mw_employees e LEFT JOIN dbo.acd_mw_departments d ON d.department_id=e.department_id WHERE e.is_active=1 ORDER BY e.full_name");
  echo '<div class="wizard-layout wizard-layout-employee"><section class="wizard-panel employee-picker-panel"><div class="wizard-panel-heading"><div><p class="wizard-kicker">Step 1 of 6</p><h2>Select employee</h2><p>Choose the employee this waiver is for.</p></div></div><div class="employee-toolbar"><label class="wizard-search"><span aria-hidden="true">'.wizard_option_icon('employee').'</span><input id="employee-search" type="search" placeholder="Search by employee name or ID" data-employee-search></label><label class="wizard-select"><select aria-label="Department filter" data-department-filter><option value="">All departments</option>';
  $departments=[];foreach($emps as $emp){$departments[(string)$emp['department_name']]=true;}foreach(array_keys($departments) as $department)echo '<option value="'.e($department).'">'.e($department).'</option>';
  echo '</select></label></div><form method="post" data-employee-form>'.csrf_field().'<input type="hidden" name="action" value="start"><div class="employee-results wizard-employee-results" data-employee-results>';
  foreach($emps as $emp){$initial=strtoupper(substr((string)$emp['full_name'],0,1));echo '<label class="employee-choice" data-employee-row data-employee-text="'.e(strtolower($emp['full_name'].' '.$emp['employee_number'])).'" data-department="'.e($emp['department_name']??'').'" data-employee-name="'.e($emp['full_name']).'" data-employee-number="'.e($emp['employee_number']).'" data-employee-position="'.e($emp['position']??'').'" data-employee-department="'.e($emp['department_name']??'').'" data-employee-email="'.e($emp['email']??'').'"><input type="radio" name="employee_id" value="'.e($emp['employee_id']).'" required><span class="avatar employee-avatar">'.e($initial).'</span><span class="employee-choice-copy"><b>'.e($emp['full_name']).'</b><small>'.e($emp['employee_number'].' · '.$emp['department_name'].' · '.$emp['position']).'</small></span><em data-selected-label> </em></label>';}echo '</div><div class="wizard-footer"><span class="results-count" data-employee-count>Showing '.e(count($emps)>0?1:0).'–'.e(min(6,count($emps))).' of '.e(count($emps)).' employees</span><div class="employee-pagination" data-employee-pagination><button type="button" class="page-button" data-employee-prev aria-label="Previous employees">‹</button><span data-employee-pages></span><button type="button" class="page-button" data-employee-next aria-label="Next employees">›</button></div><div class="wizard-actions"><a class="btn secondary" href="index.php?page=dashboard">Cancel</a><button class="btn" type="submit" data-employee-continue disabled>Continue to waiver type <span aria-hidden="true">→</span></button></div></div></form></section><aside class="wizard-panel selected-employee-panel" data-selected-employee-panel><h2>Selected employee</h2><div class="selected-employee-empty"><span class="selected-employee-symbol" aria-hidden="true">♙</span><h3>No employee selected</h3><p>Select an employee from the list to continue.</p></div></aside></div>';
 }elseif($step===2){
  echo '<div class="wizard-layout"><section class="wizard-panel type-picker-panel"><div class="wizard-panel-heading"><p class="wizard-kicker">Step 2 of 6</p><h2>Choose waiver type</h2><p>Select the situation that best applies to this employee.</p></div><form method="post" data-type-form>'.csrf_field().'<input type="hidden" name="action" value="type"><div class="type-grid wizard-type-grid"><label class="type-card"><input type="radio" name="waiver_type" value="UNFIT_TO_WORK" required><span class="type-icon">♙</span><b>Unfit to work</b><p>The employee was advised not to work but chooses to continue.</p><small>Requires recommendation and employee acknowledgment</small></label><label class="type-card"><input type="radio" name="waiver_type" value="REFUSED_MEDICAL_TREATMENT" required><span class="type-icon">✚</span><b>Refused medical treatment</b><p>The employee declines recommended treatment, evaluation, or transport.</p><small>Requires treatment details and employee acknowledgment</small></label></div><div class="wizard-footer"><a class="btn secondary" href="index.php?page=new-waiver&step=1">Back</a><button class="btn" type="submit" disabled>Continue to details <span aria-hidden="true">→</span></button></div></form></section>'.wizard_employee_summary($employee,true).'</div>';
 }elseif($step===3){
  $type=(string)($draft['type_code']??'');echo '<div class="wizard-layout"><section class="wizard-panel details-panel"><div class="wizard-panel-heading inline-heading"><div><p class="wizard-kicker">Step 3 of 6</p><h2>Waiver details</h2><p>Enter the medical recommendation and supporting information.</p></div><span class="document-kicker">'.e(str_replace('_',' ',$type)).'</span></div><form method="post" class="form-grid wizard-form">'.csrf_field().'<input type="hidden" name="action" value="details"><div class="field"><label>Date</label><input disabled value="'.e($editing?$editing['waiver_date']:date('F j, Y')).'"></div><div class="field"><label>Time</label><input disabled value="'.e($editing?$editing['waiver_time']:date('g:i A')).'"></div><div class="field full"><label>Medical / nurse personnel</label><input name="medical_personnel" value="'.e($editing['medical_personnel_name']??'').'" placeholder="Select medical personnel" required></div><div class="field full"><label>Recommendation <span class="required-mark">*</span></label><p class="field-help">Describe the recommendation provided to the employee.</p><textarea name="recommendation" maxlength="1000" placeholder="Enter the medical recommendation..." required>'.e($editing['recommendation']??'').'</textarea></div>';
  if($type==='REFUSED_MEDICAL_TREATMENT'){echo '<div class="field"><label>Transportation offered</label><select name="transportation">';foreach(TRANSPORTATION_OPTIONS as $option)echo '<option'.(($editing['transportation_offered']??'')===$option?' selected':'').'>'.e($option).'</option>';echo '</select></div>';}
  $detailsBack=$editing?'index.php?page=new-waiver&step=4&id='.(int)$editing['waiver_id']:'index.php?page=new-waiver&step=2';
  echo '<div class="field full"><label>Remarks <span class="optional-mark">Optional</span></label><textarea name="remarks" maxlength="1000" placeholder="Add any additional notes or context...">'.e($editing['remarks']??'').'</textarea></div><div class="wizard-footer"><a class="btn secondary" href="'.e($detailsBack).'">Back</a><button class="btn" type="submit">Review waiver <span aria-hidden="true">→</span></button></div></form></section>'.wizard_employee_summary($employee,false).'</div>';
 }elseif($step===4){
  $w=waiver((int)($_GET['id']??0));if(!$w){echo '<section class="card empty">Waiver not found.</section></div>';$html=ob_get_clean();echo $html;return;}echo '<div class="wizard-layout wizard-layout-review"><section class="wizard-panel review-panel"><div class="wizard-panel-heading inline-heading"><div><p class="wizard-kicker">Step 4 of 6</p><h2>Review waiver</h2><p>Confirm the information below before continuing to signatures.</p></div><span class="status-chip">Draft</span></div>';document_html($w,false);echo '<form method="post" class="wizard-footer review-footer">'.csrf_field().'<input type="hidden" name="action" value="review"><input type="hidden" name="waiver_id" value="'.e($w['waiver_id']).'"><label class="review-confirm"><input type="checkbox" name="review_confirm" value="1" required> <span>I have reviewed the information and confirm it is correct.</span></label><a class="btn secondary" href="index.php?page=new-waiver&step=3&id='.e($w['waiver_id']).'">Back to details</a><button class="btn" type="submit">Continue to signatures <span aria-hidden="true">→</span></button></form></section><aside class="wizard-panel review-summary"><h2>Review summary</h2><div class="summary-checks"><p>✓ Employee selected</p><p>✓ Waiver type selected</p><p>✓ Required details complete</p></div><div class="summary-note"><b>Document ready</b><p>The exact waiver text will be retained with this record.</p></div></aside></div>';
 }else{
  $w=waiver((int)($_GET['id']??0));if($w)complete_html($w);else echo '<section class="card empty">Waiver not found.</section>';
 }
 $html=ob_get_clean();
 $html=str_replace(
  ['<span class="selected-employee-symbol" aria-hidden="true">♙</span>','<span class="selected-employee-symbol">♙</span>','<span class="type-icon">♙</span>','<span class="type-icon">✚</span>'],
  ['<span class="selected-employee-symbol" aria-hidden="true">'.$employeeIcon.'</span>','<span class="selected-employee-symbol">'.$employeeIcon.'</span>','<span class="type-icon">'.$unfitIcon.'</span>','<span class="type-icon">'.$medicalIcon.'</span>'],
  $html
 );
 echo $html;
}
function wizard_employee_summary(?array $employee,bool $withChange):string{ob_start();?><aside class="wizard-panel employee-summary"><h2>Selected employee</h2><?php if($employee):?><div class="summary-identity"><span class="avatar"><?=e(strtoupper(substr((string)$employee['full_name'],0,1)))?></span><div><h3><?=e($employee['full_name'])?></h3><p><?=e($employee['employee_number'])?></p><span class="active-chip">✓ Active</span></div></div><dl><div><dt>Department</dt><dd><?=e($employee['department_name']??'')?></dd></div><div><dt>Position</dt><dd><?=e($employee['position']??'')?></dd></div><div><dt>Email</dt><dd><?=e($employee['email']??'Not provided')?></dd></div></dl><div class="summary-note">ⓘ <span><?= $withChange?'The selected waiver type determines the details and acknowledgment shown in the next steps.':'You can review and edit all information in the next step.'?></span></div><?php if($withChange):?><a class="summary-link" href="index.php?page=new-waiver&step=1">Change employee</a><?php endif;?><?php else:?><div class="selected-employee-empty"><span class="selected-employee-symbol">♙</span><h3>No employee selected</h3><p>Return to the employee step to continue.</p></div><?php endif;?></aside><?php return ob_get_clean();}
function waiver_route(array $r,bool $approval=false):array{if($approval)return["index.php?page=approval-sign&id={$r['waiver_id']}",'Review'];return match($r['status']){'DRAFT'=>["index.php?page=new-waiver&step=4&id={$r['waiver_id']}",'Continue'],'AWAITING_EMPLOYEE_SIGNATURE'=>["index.php?page=new-waiver&step=5&id={$r['waiver_id']}",'Continue signing'],'AWAITING_SUPERVISOR'=>in_array(user()['role_name'],['SUPERVISOR','SYSTEM ADMIN'],true)?["index.php?page=approval-sign&id={$r['waiver_id']}",'Review & sign']:["index.php?page=waiver-view&id={$r['waiver_id']}",'View'],default=>["index.php?page=waiver-view&id={$r['waiver_id']}",'View']};}
function table_html(array $rows,bool $approval=false):string{if(!$rows)return'<div class="empty">No waivers found.</div>';ob_start();?><table><thead><tr><th>Waiver</th><th>Employee</th><th>Department</th><th>Type</th><th>Status</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($rows as $r):[$url,$label]=waiver_route($r,$approval);?><tr><td><b><?=e($r['waiver_number']??'Draft')?></b></td><td><?=e($r['full_name'])?><small class="cell-sub"><?=e($r['employee_number'])?></small></td><td><?=e($r['department_name'])?></td><td><?=e($r['type_name'])?></td><td><?=badge($r['status'])?></td><td><?=e(display_datetime($r['created_at']))?></td><td><a class="btn secondary" href="<?=e($url)?>"><?=e($label)?></a></td></tr><?php endforeach?></tbody></table><?php return ob_get_clean();}
function document_html(array $w,bool $signed):void{?><article class="legal-document"><header><span>Company internal record</span><h2>WAIVER OF LIABILITY</h2><h3><?=e($w['type_name'])?></h3><div><?=e($w['waiver_number']??'DRAFT — NOT FINALIZED')?></div></header><section><h4>Employee information</h4><dl class="document-grid"><div><dt>Name</dt><dd><?=e($w['employee_name'])?></dd></div><div><dt>Employee number</dt><dd><?=e($w['employee_number'])?></dd></div><div><dt>Department</dt><dd><?=e($w['department_name'])?></dd></div><div><dt>Position</dt><dd><?=e($w['position'])?></dd></div></dl></section><section><h4>Waiver details</h4><dl class="document-grid"><div><dt>Date / time</dt><dd><?=e($w['waiver_date'].' '.$w['waiver_time'])?></dd></div><div><dt>Medical / nurse personnel</dt><dd><?=e($w['medical_personnel_name'])?></dd></div><div class="wide"><dt>Recommendation</dt><dd><?=e($w['recommendation'])?></dd></div><div><dt>Transportation</dt><dd><?=e($w['transportation_offered'])?></dd></div></dl></section><section><h4>Waiver statement</h4><p class="waiver-copy"><?=nl2br(e($w['signed_waiver_text']))?></p></section><section><h4>Acknowledgments</h4><?php foreach(acknowledgments($w['type_code']) as $x):?><p class="document-ack">□ <?=e($x)?></p><?php endforeach?></section><?php if($signed):?><section><h4>Signatures</h4><div class="signature-grid"><div><b>Employee</b><?php if($w['employee_signature']):?><img src="<?=e($w['employee_signature'])?>" alt="Employee signature"><?php endif?><p><?=e($w['employee_printed']??'Pending')?></p><small><?=e($w['employee_signed_at']??'Not signed')?></small></div><div><b>Supervisor</b><?php if($w['supervisor_signature']):?><img src="<?=e($w['supervisor_signature'])?>" alt="Supervisor signature"><?php endif?><p><?=e($w['supervisor_printed']??'Pending')?></p><small><?=e($w['supervisor_signed_at']??'Not signed')?></small></div></div><?php if($w['document_hash']):?><p class="hash">Document hash: <?=e($w['document_hash'])?></p><?php endif?></section><?php endif?></article><?php }
function signature_form(string $id):string{return'<div class="form-grid"><div class="field full"><label>Printed legal name</label><input name="printed_name" required></div><div class="field full"><label>Signature</label><div class="signature"><canvas width="800" height="260" data-signature="'.$id.'_signature"></canvas><button type="button" data-clear>Clear</button></div><input type="hidden" id="'.$id.'_signature" name="signature"></div></div>';}
function complete_html(array $w):void{?><section class="completion"><span class="completion-mark">✓</span><h2><?=$w['status']==='COMPLETED'?'Waiver completed':'Employee signed'?></h2><p><?=e($w['waiver_number']??'Waiting for supervisor acknowledgment')?></p><div class="completion-list"><span>Employee signature <b>✓ Completed</b></span><span>Supervisor signature <b><?=$w['supervisor_signed_at']?'✓ Completed':'Pending'?></b></span><span>Finalized <b><?=$w['finalized_at']?'✓ Completed':'Pending'?></b></span></div><div class="actions"><a class="btn" href="index.php?page=waiver-view&id=<?=e($w['waiver_id'])?>">View waiver</a><a class="btn secondary" href="index.php?page=new-waiver&step=1">Create another</a></div></section><?php }
